import { FC } from 'react';
import { Tooltip } from '@patternfly/react-core/dist/dynamic/components/Tooltip';
import { BellIcon } from '@patternfly/react-icons/dist/dynamic/icons/bell-icon';
import { CheckIcon } from '@patternfly/react-icons/dist/dynamic/icons/check-icon';
import { BellSlashIcon } from '@patternfly/react-icons/dist/dynamic/icons/bell-slash-icon';
import { useTranslation } from 'react-i18next';
import { GroupedAlert, IncidentsDetailsAlert } from '../types/model';

interface IncidentAlertStateIconProps {
  alertDetails: IncidentsDetailsAlert;
  showTooltip?: boolean;
}

const getAlertState = (alertDetails: IncidentsDetailsAlert): 'firing' | 'resolved' | 'silenced' => {
  if (alertDetails.silenced) {
    return 'silenced';
  }
  if (alertDetails.resolved) {
    return 'resolved';
  }

  return 'firing';
};

export const IncidentAlertStateIcon: FC<IncidentAlertStateIconProps> = ({
  alertDetails,
  showTooltip = true,
}) => {
  const { t } = useTranslation(process.env.I18N_NAMESPACE);
  const state = getAlertState(alertDetails);

  const getIconAndTooltip = () => {
    switch (state) {
      case 'firing':
        return {
          icon: <BellIcon />,
          tooltip: t('Firing'),
        };
      case 'resolved':
        return {
          icon: <CheckIcon />,
          tooltip: t('Resolved'),
        };
      case 'silenced':
        return {
          icon: <BellSlashIcon style={{ color: 'var(--pf-t--global--icon--color--disabled)' }} />,
          tooltip: t('Silenced'),
        };
      default:
        return {
          icon: <BellIcon />,
          tooltip: t('Unknown'),
        };
    }
  };

  const { icon, tooltip } = getIconAndTooltip();

  if (showTooltip) {
    return <Tooltip content={tooltip}>{icon}</Tooltip>;
  }

  return icon;
};

interface GroupedAlertStateIconProps {
  groupedAlert: GroupedAlert;
  showTooltip?: boolean;
}
const getGroupedAlertState = (groupedAlert: GroupedAlert): 'firing' | 'resolved' | 'silenced' => {
  if (groupedAlert.alertstate === 'silenced') {
    return 'silenced';
  }
  if (groupedAlert.alertstate === 'resolved') {
    return 'resolved';
  }
  return 'firing';
};

export const GroupedAlertStateIcon: FC<GroupedAlertStateIconProps> = ({
  groupedAlert,
  showTooltip = true,
}) => {
  const { t } = useTranslation(process.env.I18N_NAMESPACE);
  const state = getGroupedAlertState(groupedAlert);

  const getIconAndTooltip = () => {
    switch (state) {
      case 'firing':
        return {
          icon: <BellIcon />,
          tooltip: t('Firing'),
        };
      case 'resolved':
        return {
          icon: <CheckIcon />,
          tooltip: t('Resolved'),
        };
      case 'silenced':
        return {
          icon: <BellSlashIcon style={{ color: 'var(--pf-t--global--icon--color--disabled)' }} />,
          tooltip: t('Silenced'),
        };
      default:
        return {
          icon: <BellIcon />,
          tooltip: t('Unknown'),
        };
    }
  };

  const { icon, tooltip } = getIconAndTooltip();

  if (showTooltip) {
    return <Tooltip content={tooltip}>{icon}</Tooltip>;
  }

  return icon;
};
